--
-- Table structure for table `panel_investigador`
--

DROP TABLE IF EXISTS `panel_investigador`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `panel_investigador` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sesion_id` int NOT NULL,
  `usuario_id` int NOT NULL,
  `paso` int NOT NULL,
  `item_id` int NOT NULL,
  `item_clave` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_b` float DEFAULT NULL,
  `es_correcta` tinyint(1) DEFAULT NULL,
  `theta` float NOT NULL,
  `sem` float NOT NULL,
  `ic_inf` float DEFAULT NULL COMMENT '? - 1.96*SEM',
  `ic_sup` float DEFAULT NULL COMMENT '? + 1.96*SEM',
  `nivel_momentaneo` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Clasificación en ese instante',
  `timestamp` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_panel_sesion` (`sesion_id`),
  KEY `idx_panel_usuario` (`usuario_id`),
  CONSTRAINT `panel_investigador_ibfk_1` FOREIGN KEY (`sesion_id`) REFERENCES `sesiones_examen` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

