--
-- Table structure for table `respuestas`
--

DROP TABLE IF EXISTS `respuestas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `respuestas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sesion_id` int NOT NULL,
  `item_id` int NOT NULL,
  `orden` int NOT NULL COMMENT 'Posición en la secuencia del CAT',
  `respuesta_dada` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `es_correcta` tinyint(1) NOT NULL,
  `theta_post` float NOT NULL COMMENT '? actualizado tras esta respuesta',
  `sem_post` float NOT NULL COMMENT 'SEM actualizado tras esta respuesta',
  `delta_theta` float DEFAULT NULL COMMENT '|?_actual - ?_anterior| para criterio de parada',
  `respondido_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `item_id` (`item_id`),
  KEY `idx_respuestas_sesion` (`sesion_id`),
  CONSTRAINT `respuestas_ibfk_1` FOREIGN KEY (`sesion_id`) REFERENCES `sesiones_examen` (`id`) ON DELETE CASCADE,
  CONSTRAINT `respuestas_ibfk_2` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

