--
-- Table structure for table `sesiones_examen`
--

DROP TABLE IF EXISTS `sesiones_examen`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sesiones_examen` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int NOT NULL COMMENT 'Un examen por usuario',
  `estado` enum('pendiente','en_progreso','completado','saltado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `theta_actual` float DEFAULT '0' COMMENT '? estimado actual',
  `sem_actual` float DEFAULT '1' COMMENT 'Error estándar actual',
  `theta_inicial` float DEFAULT '0' COMMENT '? de arranque según encuesta',
  `pasos_sin_cambio` int DEFAULT '0' COMMENT 'Contador para criterio de estancamiento',
  `nivel_resultado` enum('principiante','intermedio','avanzado') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `theta_final` float DEFAULT NULL,
